// -----------------------------------------------------------------------------
// The IPMA forecast locations: one per municipality of mainland Portugal,
// Madeira and the Azores, plus a few named points (423 in all).
//
// The table is static (src/locations-data.js, generated by
// scripts/build-locations.mjs): the manifest select lists the same entries,
// and a location's `globalIdLocal` is the platform id of its device, so it
// never changes once published.
// -----------------------------------------------------------------------------

import { LOCATION_ROWS } from './locations-data.js';

// District (mainland) or island of each `idDistrito`.
const DISTRICTS = {
  1: 'Aveiro',
  2: 'Beja',
  3: 'Braga',
  4: 'Bragança',
  5: 'Castelo Branco',
  6: 'Coimbra',
  7: 'Évora',
  8: 'Faro',
  9: 'Guarda',
  10: 'Leiria',
  11: 'Lisboa',
  12: 'Portalegre',
  13: 'Porto',
  14: 'Santarém',
  15: 'Setúbal',
  16: 'Viana do Castelo',
  17: 'Vila Real',
  18: 'Viseu',
  31: 'Madeira',
  32: 'Porto Santo',
  41: 'Santa Maria',
  42: 'São Miguel',
  43: 'Terceira',
  44: 'Graciosa',
  45: 'São Jorge',
  46: 'Pico',
  47: 'Faial',
  48: 'Flores',
  49: 'Corvo',
};

// IPMA dates its forecasts and warnings in the local time of the place.
const TIME_ZONES = { 1: 'Europe/Lisbon', 2: 'Atlantic/Madeira', 3: 'Atlantic/Azores' };

/**
 * @typedef {object} Location
 * @property {number} id IPMA globalIdLocal, e.g. 1010500 for Aveiro
 * @property {string} name
 * @property {number} region 1 mainland, 2 Madeira, 3 Azores
 * @property {string} district district or island name
 * @property {string} dico municipality code of the fire risk files ("0105")
 * @property {string} area warning area (idAreaAviso), e.g. "AVR"
 * @property {number} latitude
 * @property {number} longitude
 * @property {string} timeZone
 */

/** @type {Location[]} */
export const LOCATIONS = LOCATION_ROWS.map(
  ([id, name, districtId, municipalityId, area, latitude, longitude]) => {
    const region = Math.floor(id / 1000000);
    return {
      id,
      name,
      region,
      district: DISTRICTS[districtId] ?? '',
      dico: `${String(districtId).padStart(2, '0')}${String(municipalityId).padStart(2, '0')}`,
      area,
      latitude,
      longitude,
      timeZone: TIME_ZONES[region] ?? TIME_ZONES[1],
    };
  },
);

const BY_ID = new Map(LOCATIONS.map((location) => [location.id, location]));

/** The fire risk (RCM) is only forecast for mainland Portugal. */
export const hasFireRisk = (location) => location.region === 1;

/**
 * Label of a location in the select and in messages: "Albufeira (Faro)",
 * "Horta (Faial, Açores)". Portuguese place names, the same in every
 * language.
 */
export function locationLabel(location) {
  const district = location.district;
  if (location.region === 3) {
    return `${location.name} (${district}, Açores)`;
  }
  return district ? `${location.name} (${district})` : location.name;
}

/** @returns {Location|undefined} */
export function locationById(id) {
  return BY_ID.get(Number(id));
}

// Case and accent insensitive comparison of names typed by hand.
const fold = (text) =>
  String(text)
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const BY_NAME = new Map(LOCATIONS.map((location) => [fold(location.name), location]));
const BY_LABEL = new Map(LOCATIONS.map((location) => [fold(locationLabel(location)), location]));

/**
 * Find a location from what a user typed: its IPMA id ("1010500"), its name
 * ("Ílhavo", "ilhavo") or its full label ("Lagoa (Faro)").
 * @returns {Location|undefined}
 */
export function findLocation(text) {
  const value = String(text ?? '').trim();
  if (value === '') {
    return undefined;
  }
  if (/^\d+$/.test(value)) {
    return locationById(value);
  }
  const key = fold(value);
  return BY_NAME.get(key) ?? BY_LABEL.get(key);
}

/**
 * Parse a list of locations typed by hand, separated by commas, semicolons
 * or line breaks.
 * @returns {{ locations: Location[], unknown: string[] }}
 */
export function parseLocationList(text) {
  const locations = [];
  const unknown = [];
  for (const part of String(text ?? '').split(/[,;\n]+/)) {
    const value = part.trim();
    if (value === '') {
      continue;
    }
    const location = findLocation(value);
    if (location) {
      locations.push(location);
    } else {
      unknown.push(value);
    }
  }
  return { locations, unknown };
}

const toRadians = (degrees) => (degrees * Math.PI) / 180;

/** Great-circle distance in km between two { latitude, longitude }. */
export function distanceKm(a, b) {
  const dLat = toRadians(b.latitude - a.latitude);
  const dLon = toRadians(b.longitude - a.longitude);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRadians(a.latitude)) * Math.cos(toRadians(b.latitude)) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.min(1, Math.sqrt(h)));
}

/**
 * The location closest to a point.
 * @returns {{ location: Location, distance: number }}
 */
export function nearestLocation(point) {
  let best = null;
  for (const location of LOCATIONS) {
    const distance = distanceKm(point, location);
    if (best === null || distance < best.distance) {
      best = { location, distance };
    }
  }
  return best;
}
